INSERT INTO legal_concepts (id, concept, category, subcategory, definition_simple, real_example, regulation, jurisprudence, video_url, key_points) VALUES
('DPNAL-001', 'Tipicidad', 'Derecho Penal', 'Teoría del Delito', 'Adecuación de una conducta concreta a la descripción legal de un delito (tipo penal), de modo que el comportamiento encaje estrictamente en el supuesto de hecho previsto por la ley penal', 'Ej.: La acción de Juan al golpear a Pedro es típica porque se subsume en el delito de lesiones (Art. 397 CP)', 'Art. 1 inc. 1° CP', '', '', '["Fundamento del principio nullum crimen sine lege: sin tipicidad no hay delito, discutiéndose si el juez debe interpretar estrictamente el tipo o puede aplicar analogías en favor del reo", "Controversia sobre tipos penales abiertos: algunos autores critican descripciones vagas que otorgan excesiva discrecionalidad judicial en la determinación de la tipicidad"]'),
('DPNAL-002', 'Antijuridicidad', 'Derecho Penal', 'Teoría del Delito', 'Contrariedad de la conducta típica al ordenamiento jurídico, esto es, que el hecho típico no esté amparado por una causa de justificación y por tanto lesione el bien jurídico protegido', 'Ej.: Causar lesiones a otro es antijurídico salvo que medie legítima defensa, en cuyo caso el acto se justifica (no es antijurídico)', 'Art. 10 CP (causales justificantes, ej. legítima defensa)', '', '', '["Debate doctrinal sobre la antijuridicidad material vs formal: si basta la infracción legal o se requiere además lesionar de forma efectiva el bien jurídico", "Conflicto en jurisprudencia al aplicar causas de justificación: criterios dispares sobre cuándo se configura legítima defensa o estado de necesidad, generando inseguridad en la valoración de la antijuridicidad"]'),
('DPNAL-003', 'Culpabilidad', 'Derecho Penal', 'Teoría del Delito', 'Juicio de reproche personal al autor por la realización del hecho antijurídico, presupone la capacidad de imputación y un elemento subjetivo de responsabilidad (dolo o culpa) al momento del hecho', 'Ej.: Un inimputable (ej. un enfermo mental profundo) no actúa con culpabilidad, pues carece de capacidad de comprender su acto, a diferencia de un adulto en pleno juicio que delinque y se le reprocha el delito', 'Art. 10 N°1 y 2 CP', '', '', '["Tensión entre teorías psicológicas vs normativas de la culpabilidad: mientras unas se centran en la voluntad o conciencia del autor, otras la conciben como un juicio normativo de reprochabilidad", "Disputa sobre el dolo eventual: algunos fallos han equiparado dolo eventual a culpa consciente en materia de responsabilidad, generando debate sobre los límites de la culpabilidad en casos de riesgo aceptado"]'),
('DPNAL-004', 'Dolo', 'Derecho Penal', 'Teoría del Delito', 'Voluntad consciente de realizar el tipo penal, conociendo los elements del hecho y queriendo su realización (intención deliberada de delinquir)', 'Ej.: Quien apunta y dispara a otro con la intención de matarlo actúa con dolo homicida', 'Art. 2° CP (diferencia dolo y culpa)', 'Corte Suprema, Rol 2882-2017 (05/05/2021): se reafirmó que el dolo supone el conocimiento y voluntad dirigida al resultado, distinguiéndolo del dolo eventual donde el autor se representa el resultado posible y lo acepta', '', '["Discusión sobre el dolo eventual: la jurisprudencia chilena ha oscilado en sus criterios para diferenciarlo de la culpa consciente, generando inseguridad sobre cuándo hay aceptación del resultado vs mera imprudencia", "Controversia doctrinal sobre si el error de prohibición (desconocimiento de ilicitud) afecta el dolo: para algunos anula la culpabilidad sin excluir el dolo, para otros impide formarse la intención dolosa plena"]'),
('DPNAL-005', 'Culpa (Negligencia)', 'Derecho Penal', 'Teoría del Delito', 'Falta de diligencia o cuidado debido en la actuación, de modo que el resultado típico es causado por imprudencia, descuido o impericia, sin intención dolosa', 'Ej.: Un conductor que, por distraerse con el teléfono, atropella a un peatón, actúa con culpa al infringir su deber de cuidado', 'Art. 2° CP (las acciones que serían delito doloso se califican de cuasidelito si hay solo culpa)', '', '', '["Problema práctico en la graduación de la culpa: la distinción entre culpa leve, grave o gravísima ha sido objeto de interpretaciones dispares en jurisprudencia civil vs penal", "Debate sobre la punibilidad de la culpa: mientras algunos abogan por sancionar solo conductas dolosas salvo casos específicos, otros sostienen la necesidad de castigar la negligencia criminal grave para tutelar bienes jurídicos"]'),
('DPNAL-006', 'Actos preparatorios', 'Derecho Penal', 'Iter Criminis', 'Fase inicial del iter criminis consistente en actos de planificación o preparación del delito, que por regla general no se sancionan penalmente, salvo que la ley expresamente los tipifique (como conspiración o proposición para ciertos delitos)', 'Ej.: Reunir armas y hacer vigilancias para robar un banco son actos preparatorios no punibles, a menos que se tipifique conspiración (acuerdo entre varios) para ese delito', 'Art. 8 CP (solo punibles conspiración y proposición en casos especiales)', '', '', '["Debate doctrinal sobre punibilidad temprana: extender la punibilidad a actos preparatorios podría chocar con el principio de lesividad, discutiéndose en qué punto el plan criminal pasa de lo puramente interno a afectar bienes jurídicos", "Críticas a figuras de conspiración amplias: se señala que pueden castigar intenciones no materializadas, mientras que otros defienden su punición para prevenir delitos graves en etapa incipiente"]'),
('DPNAL-007', 'Tentativa', 'Derecho Penal', 'Iter Criminis', 'Inicio de la ejecución de un delito por actos directos, sin lograr su consumación por causas ajenas a la voluntad del autor', 'Ej.: El autor dispara contra la víctima pero falla el tiro y ésta sobrevive', 'se configura tentativa de homicidio al haber comenzado la ejecución del crimen sin consumarlo', 'Art. 7 inc. final CP (definición de tentativa)', '', '[]'),
('DPNAL-008', 'Delito frustrado', 'Derecho Penal', 'Iter Criminis', 'Situación en que el autor realiza todos los actos necesarios para consumar el delito, pero el resultado no ocurre por causas independientes de su voluntad', 'Ej.: El homicida apuñala a la víctima en una zona vital creyendo causarle la muerte, pero ésta es socorrida a tiempo y sobrevive', 'el hecho constituye homicidio frustrado', 'Art. 7 inc. 2° CP (definición de delito frustrado)', '', '[]'),
('DPNAL-009', 'Delito consumado', 'Derecho Penal', 'Iter Criminis', 'Etapa final del iter criminis donde se han realizado plenamente todos los elementos del tipo penal y el resultado exigido (si lo hay) se ha verificado, configurándose así el delito en su integridad', 'Ej.: En un homicidio consumado, la víctima efectivamente muere a causa de la acción del autor, cumpliéndose todos los elements del tipo penal', 'Art. 7 inc. 1° CP (se sanciona el delito consumado)', '', '', '["Cuestión controvertida de la consumación en delitos de resultado vs de mera actividad: en delitos formales la consumación coincide con la realización de la conducta típica, mientras que en delitos materiales se debate el momento exacto (ej. ¿se consuma el hurto al tomar la cosa o al asegurar su poder?), lo que ha llevado a fallos que a veces la consideran consumada con la sola aprehensión de la cosa mediante violencia, sin exigir salir del lugar, para unificar criterios"]'),
('DPNAL-010', 'Desistimiento voluntario', 'Derecho Penal', 'Iter Criminis', 'Abandono intencional de la ejecución del delito por parte del autor antes de consumarlo, evitando por su propia voluntad que el delito se complete', 'Ej.: Un asaltante que, ya encañonando a la víctima, decide no cometer el robo y huye sin tomar nada, se acoge al desistimiento voluntario, quedando exento de pena por tentativa', 'Art. 7 inc. 2° CP (no hay frustrado si la no consumación se debe a la voluntad del autor)', '', '', '["Debate sobre la naturaleza del desistimiento: algunos lo conciben como una causa de exclusión de punibilidad (beneficio al autor arrepentido), mientras otros discuten si en realidad no llega a haber tentativa punible por ausencia de consumación por voluntad propia", "Problema probatorio: la frontera entre desistimiento voluntario y tentativa inacabada frustrada por factores externos puede ser difusa, recayendo en tribunales la evaluación de si el autor abandonó el delito por arrepentimiento genuino o por obstáculos ajenos a su voluntad"]'),
('DPNAL-011', 'Autoría', 'Derecho Penal', 'Participación Criminal', 'Calidad de quien comete el delito por sí mismo o concurre directamente a su ejecución con dominio del hecho, siendo considerado autor inmediato o mediato según el caso', 'Ej.: El sujeto que dispara y da muerte a la víctima es autor directo del homicidio', 'igualmente el que ordena a un menor inimputable cometerlo actúa como autor mediato', 'Art. 15 CP', '', '["CS, Causa rol 134.116-2022: Estableció que es autor quien realiza por sí la conducta típica o se sirve de otro como instrumento, conservando el control del hecho"]'),
('DPNAL-012', 'Coautoría', 'Derecho Penal', 'Participación Criminal', 'Forma de autoría conjunta en la que dos o más personas, con un acuerdo común (expreso o tácito), ejecutan el delito repartiendo funciones y teniendo cada uno poder de decisión sobre la realización del hecho', 'Ej.: Dos individuos que planifican y llevan a cabo juntos un secuestro, dividiéndose tareas (uno reduce a la víctima y otro conduce el vehículo), actúan en coautoría', 'Art. 15 N°1 CP', 'La jurisprudencia (CS Rol 43.974-2020) ha señalado que en la coautoría existe un “dominio funcional del hecho”, pues los coautores se reparten el trabajo delictivo de modo que ninguno por sí solo realiza el delito completo', '', '["Controversia sobre el requisito del acuerdo común: la doctrina tradicional exige un acuerdo previo para la coautoría, mientras corrientes más modernas admiten la coautoría impropia o sucesiva sin plan previo, lo que genera debates en casos donde el concierto entre partícipes es difuso", "Problemática en la imputación recíproca: en la coautoría todos responden por el hecho total, pero han surgido discusiones sobre si cada coautor responde por excesos individuales de otro, cuestión que jurisprudencia ha resuelto caso a caso"]'),
('DPNAL-013', 'Autoría mediata', 'Derecho Penal', 'Participación Criminal', 'Modalidad de autoría en que el sujeto realiza el delito sirviéndose de otra persona como instrumento, aprovechando que esta última no será penada (por falta de dolo, coacción, inimputabilidad u otro)', 'Ej.: Quien manipula a un inimputable para que incendie un local comete el delito como autor mediato, usando al ejecutor material como medio', 'Art. 15 N°2 CP', 'Corte Suprema (Caso La Serena, 2024) precisó que el autor mediato “domina el hecho” a través del control de la voluntad del ejecutor, instrumentalizando a otra persona para la ejecución típica', '', '["Debate doctrinal sobre si la autoría mediata cabe cuando el instrumento actúa con dolo (autor mediato en estructuras organizadas): a raíz de casos de criminalidad macro, se discute si un líder puede ser autor mediato teniendo subordinados plenamente imputables, asunto que divide la doctrina y ha tenido reconocimiento dispar en tribunales", "Problema probatorio: demostrar la autoría mediata requiere probar la influencia determinante del autor en el instrumentado, lo que genera dificultades prácticas y estándares de prueba elevados para acreditar ese dominio de la voluntad ajena"]'),
('DPNAL-014', 'Cómplice', 'Derecho Penal', 'Participación Criminal', 'Partícipe secundario que colabora con la ejecución del delito realizando actos no esenciales, ya sea antes o durante la perpetración, sin ejecutar el núcleo del tipo ni tener el dominio del hecho', 'Ej.: El chofer que espera en el auto para facilitar la huida en un robo, sin entrar al lugar, actúa como cómplice del robo al cooperar en la comisión', 'Art. 16 CP', 'La jurisprudencia ha caracterizado la complicidad como una intervención periférica de apoyo al autor, requiriendo que el hecho principal se consume o al menos se inicie para que haya punibilidad del cómplice', '', '["Discrepancia sobre la punibilidad del cómplice cuando el autor es inimputable o no ha sido condenado: doctrinariamente se debate si puede haber complicidad sin autor punible, discutiéndose el principio de accesoriedad de la participación, lo cual ha llevado a soluciones distintas en jurisprudencia comparada", "Cuestión de grado: distinguir entre cómplice y coautor suele ser conflictivo en casos de aportes relevantes"]'),
('DPNAL-015', 'Encubridor', 'Derecho Penal', 'Participación Criminal', 'Quien interviene tras la comisión del delito, sin haber participado en él como autor ni cómplice, prestando ayuda al delincuente para eludir la acción de la justicia o aprovecharse del delito', 'Ej.: Una persona que oculta en su casa al autor de un homicidio para evitar que la policía lo capture actúa como encubridor, al asistirlo después del crimen', 'Art. 17 CP', 'La doctrina jurisprudencial consolidada indica que el encubridor realiza actos de favorecimiento post-delictual (ocultación de autores, bienes o evidencias) con conocimiento del delito, diferenciándolo del cómplice por la falta de ayuda previa o concurrente a la ejecución', '', '["Debate sobre encubrimiento de parientes cercanos: si bien el Art. 17 CP exime de pena a encubridores que sean cónyuge o familiares próximos del autor, existe discusión sobre el fundamento de esta exceptio (favor familiar) y su extensión, cuestionándose en doctrina si debe mantenerse o restringirse en casos graves", "Problema práctico: distinguir encubrimiento de receptación u otros delitos autónomos puede ser complejo (p.ej., ocultar bienes robados puede ser encubrimiento del robo o receptación independiente), generando incertidumbre y necesidad de criterios claros en la jurisprudencia"]'),
('DPNAL-016', 'Legítima defensa', 'Derecho Penal', 'Circunstancias Modificatorias de Responsabilidad', 'Causal de justificación que exime de responsabilidad penal a quien repele una agresión ilegítima actual o inminente, con un medio racional y sin provocación suficiente previa', 'Ej.: Un individuo que es atacado con un cuchillo y se defiende disparando al agresor, evitando el daño a su vida, actúa en legítima defensa propia (no es punible por las lesiones causadas al agresor)', 'Art. 10 N°4 CP (defensa propia, con requisitos)', 'Corte Suprema, “Caso Martínez” (2018): confirmando absolución por legítima defensa, enfatizó que ante agresión ilegítima grave la reacción defensiva proporcional exime de pena, consolidando la doctrina de la racionalidad del medio empleado', '', '["Controversia sobre exceso en la defensa: se debate cuándo la reacción defensiva desproporcionada debe ser considerada eximente incompleta (atenuante) en lugar de legítima defensa plena, divergencia reflejada en fallos diversos sobre casos de exceso de fuerza", "Discusión doctrinal entre teorías subjetivas y objetivas: unas ponen el foco en la situación de miedo del defendiente para valorar la racionalidad del medio, mientras otras examinan estrictamente la proporcionalidad objetiva, generando distintos estándares para reconocer la legítima defensa"]'),
('DPNAL-017', 'Inimputabilidad (demencia)', 'Derecho Penal', 'Circunstancias Modificatorias de Responsabilidad', 'Causal de exclusión de culpabilidad en que el agente, por trastorno mental grave o privación total de razón, no comprende la ilicitud de sus actos ni puede autodeterminarse, quedando exento de responsabilidad penal', 'Ej.: Una persona con esquizofrenia paranoide aguda que comete un hecho violento durante un brote psicótico es declarada inimputable, no siendo condenada penalmente sino sujeta a posibles medidas de seguridad', 'Art. 10 N°1 CP', 'Corte Suprema, “Caso Zamorano” (2015): se confirmó la absolución de un acusado por estado de demencia, estableciendo que los peritajes psiquiátricos unívocos sobre la ausencia de imputabilidad obligan a eximir de pena, aplicándose internación en lugar de cárcel', '', '["Debate sobre imputabilidad disminuida: la legislación chilena no contempla expresamente grados intermedios de inimputabilidad, generando discusión doctrinal sobre casos fronterizos (p. ej., trastornos de personalidad severos) donde el sujeto no está en plena capacidad pero tampoco totalmente privado de razón", "Cuestión de prueba: la determinación de la inimputabilidad suele depender de peritajes psiquiátricos, lo que plantea desafíos en juicio al ponderar informes contradictorios, evidenciando tensiones entre criterios médicos y jurídicos para establecer la exención del Art. 10 N°1 CP"]'),
('DPNAL-018', 'Atenuante de irreprochable conducta anterior', 'Derecho Penal', 'Circunstancias Modificatorias de Responsabilidad', 'Circunstancia atenuante general consistente en que el acusado no registra comportamientos previos reprochables ni condenas, mostrando una trayectoria vital honesta antes del delito', 'Ej.: En un primer delito cometido por una persona sin antecedentes penales ni policiales, el tribunal reconoce su conducta anterior intachable como atenuante, disminuyendo la pena', 'Art. 11 N°6 CP', 'Jurisprudencia uniforme de la CS considera esta atenuante casi siempre concurrente en primarios absolutos, al punto de llamarla “la atenuante de la hoja limpia”, salvo que se pruebe un historial oculto de conductas antisociales', '', '["Polémica sobre la ponderación: se discute si esta atenuante debe valorarse con igual fuerza que otras (dado que la gran mayoría de delincuentes primarios la invocan), o si pierde eficacia por su frecuencia, lo que ha llevado a fallos que a veces la consideran atenuante muy calificada para rebajar dos grados y otros solo un grado", "Dilema en caso de funcionarios públicos: doctrinarios debaten si, tratándose de delitos cometidos por quienes tenían especial deber de probidad (ej. corrupción), la irreprochable conducta anterior debería ser excluida o al menos ponderada con menor peso, dado que su posición agrava la reprochabilidad del hecho"]'),
('DPNAL-019', 'Agravante de alevosía', 'Derecho Penal', 'Circunstancias Modificatorias de Responsabilidad', 'Circunstancia agravante que consiste en cometer el delito con medios o modos que aseguran la ejecución del hecho sin riesgo para el autor por la reacción de la víctima, actuando sobre seguro o con traición', 'Ej.: Un homicida que ataca sorpresivamente por la espalda a la víctima o la envenena a escondidas actúa con alevosía, incrementando su culpabilidad y la pena aplicable', 'Art. 12 N°1 CP', 'CS, Rol 3667-2019: En un fallo por homicidio calificado, la Corte Suprema confirmó la concurrencia de alevosía al haberse demostrado que el acusado atacó a la víctima dormida, eliminando su capacidad de defensa, constituyendo este modo traicionero una mayor reprochabilidad', '', '["Discusión sobre su aplicación en casos de violencia doméstica: se debate si en ciertos femicidios y parricidios debe estimarse alevosía cuando la víctima es atacada en contexto de confianza (traición a la relación), lo que algunos tribunales han acogido y otros han considerado inherente al tipo especial, evitando el doble agravamiento", "Principio de inherencia vs concurso de agravantes: doctrinalmente se advierte que no debe aplicarse alevosía si el modus operandi violento ya está incorporado en el delito base (p. ej., robo con violencia), punto que ha generado revocaciones de sentencias donde indebidamente se acumuló la agravante a la calificación típica"]'),
('DPNAL-020', 'Reincidencia', 'Derecho Penal', 'Circunstancias Modificatorias de Responsabilidad', 'Circunstancia agravante específica consistente en haber sido condenado anteriormente por uno o más delitos de igual o mayor gravedad, evidenciando habitualidad delictiva (Art. 12 N°15 y 16 CP)', 'Ej.: Un individuo condenado por robo que vuelve a delinquir cometiendo otro robo califica como reincidente específico, lo que agrava su pena en el nuevo juicio', 'Art. 12 N°15 y 16 CP', 'La jurisprudencia ha establecido que la reincidencia agrava la pena pero no puede, por sí sola, superar el máximum legal del delito, y exige que las condenas anteriores estén firmes y dentro de los plazos legales para ser consideradas', '', '["Debate sobre su justificación: penalistas discuten si la reincidencia vulnera el principio de non bis in ídem (al castigar de nuevo un hecho ya penado, como los antecedentes), mientras otros la defienden por reflejar mayor peligrosidad y menor posibilidad de rehabilitación", "Cuestión de sistematización: se critica la dualidad de numerales para la reincidencia en el Código (una genérica y otra específica por delito de misma especie), proponiendo reformas para unificarlas o graduarlas mejor, dado que actualmente su interpretación ha sido confusa y dejó lagunas, resueltas disímilmente por distintos tribunales"]'),
('DPNAL-021', 'Presidio (pena privativa de libertad)', 'Derecho Penal', 'Penas y Medidas de Seguridad', 'Pena consistente en la privación de libertad del condenado en un establecimiento penitenciario, con la particularidad histórica de conllevar trabajos obligatorios según el régimen carcelario (a diferencia de la reclusión que no impone trabajo)', 'Ej.: Condena a 5 años de presidio menor en su grado máximo por robo con violencia, a cumplir efectivamente en una cárcel con régimen de trabajo intramuro', 'Art. 32 CP (definición de presidio y distinción con reclusión)', '', '', '["Debate sobre trabajos forzados: aunque la legislación distingue presidio (con trabajo) de reclusión (sin trabajo), en la práctica actual ambos implican régimen laboral intrapenitenciario opcional, discutiéndose la vigencia real de la diferencia y su compatibilidad con estándares de derechos humanos", "Cuestión de grados y beneficios: la aplicación de penas de presidio ha generado interpretaciones en torno a los beneficios carcelarios (libertad condicional, rebajas por conducta) y su procedencia según la duración de la pena, siendo materia de criterios jurisprudenciales variables en cuanto a requisitos y oportuniades de acceso para los reos"]'),
('DPNAL-022', 'Multa (pena pecuniaria)', 'Derecho Penal', 'Penas y Medidas de Seguridad', 'Sanción penal de carácter patrimonial que obliga al condenado a pagar una suma de dinero al Estado, determinada generalmente en unidades tributarias (UTM) o proporción al perjuicio, según lo fijado en la ley para cada delito', 'Ej.: Pena de multa de 11 a 20 UTM impuesta a un condenado por lesiones menos graves en un juicio simplificado, equivalentes al monto establecido en la sentencia conforme al Art. 397 CP', 'Art. 467 inc. final CP (tramos de multa según el perjuicio en estafa)', '', '', '["Problemas de ejecución: frecuentemente los condenados insolventes incumplen el pago de la multa, discutiéndose alternativas como sustitución por trabajos comunitarios o reclusión por multa impaga, con posiciones encontradas sobre su eficacia y humanidad", "Crítica doctrinal: se ha cuestionado que el sistema de multas fijas en UTM pueda generar desigualdad, ya que afecta más gravosamente a quienes tienen menos recursos, proponiéndose instaurar un sistema de días-multa proporcional a los ingresos del penado para una mayor justicia en la sanción pecuniaria"]'),
('DPNAL-023', 'Inhabilitación (pena accesoria)', 'Derecho Penal', 'Penas y Medidas de Seguridad', 'Pena que priva al condenado de ciertos derechos, cargos o profesiones, sea en forma absoluta (todos los cargos públicos, derechos políticos, etc.) o especial (determinada profesión u oficio), pudiendo ser temporal o perpetua', 'Ej.: Un funcionario público condenado por cohecho recibe, además de la pena de prisión, la inhabilitación absoluta perpetua para ejercer cargos públicos (no podrá postular ni desempeñar funciones estatales de por vida)', 'Art. 21 CP (escala general incluye inhabilitaciones)', '', '', '["Debate sobre automático vs facultativo: si bien muchas inhabilitaciones se aplican de pleno derecho junto con la pena principal, se discute si el juez debería graduar su duración caso a caso en vez de aplicación rígida, para evitar sanciones excesivas en delitos menores", "Problemática de rehabilitación: sectores critican las inhabilitaciones perpetuas (ej. para cargos públicos en delitos contra la administración), señalando que obstaculizan la reinserción social del penado aun después de cumplida su condena, generando tensiones con el fin resocializador de las penas"]'),
('DPNAL-024', 'Medida de seguridad', 'Derecho Penal', 'Penas y Medidas de Seguridad', 'Consecuencia jurídica no retributiva, orientada a la protección social y tratamiento del delincuente considerado peligroso o inimputable, que se aplica en lugar o además de la pena, sujeta a revisión mientras persista la peligrosidad', 'Ej.: Un inimputable por demencia declarado autor de un delito grave es internado en un hospital psiquiátrico por medida de seguridad, hasta que sus facultades mentales se recuperen según evaluación médica', 'Art. 455 CPP (procedimiento especial para aplicar medida de seguridad a enajenados mentales)', 'CS, Rol 13.532-2017: La Corte Suprema confirmó la imposición de internación provisional a un acusado inimputable por esquizofrenia, enfatizando que la medida de seguridad no es una pena y debe cesar al desaparecer la peligrosidad derivada de la enfermedad', '', '["Controversia sobre duración potencialmente indefinida: críticos señalan que una medida de seguridad puede extenderse por más tiempo que la pena que hubiera correspondido, cuestionando su legitimidad y pidiendo controles estrictos (p. ej. revisiones periódicas obligatorias) para evitar internaciones desproporcionadas", "Debate doctrinal finalista vs preventivo: la tensión entre concebir las medidas de seguridad como instrumentos de rehabilitación vs meros mecanismos de neutralización del peligro se refleja en discusiones sobre su utilización creciente, con llamados a equilibrar seguridad pública y derechos individuales del inimputable"]'),
('DPNAL-025', 'Penas sustitutivas', 'Derecho Penal', 'Penas y Medidas de Seguridad', 'Mecanismos legales que permiten cumplir las condenas privativas o restrictivas de libertad en forma alternativa fuera de prisión, bajo ciertas condiciones de control o prestación a la comunidad, según la Ley Nº 18.216', 'Ej.: A un condenado a 2 años de presidio se le concede la remisión condicional de la pena (no ingresa a cárcel, queda sujeto a un plazo de observación con condiciones de firma)', 'Ley 18.216, Art. 1 (faculta suspender penas privativas concediendo alguna de las penas sustitutivas)', '', '', '["Debate sobre eficacia vs seguridad: partidarios sostienen que las penas sustitutivas favorecen la reinserción y evitan el hacinamiento carcelario, mientras detractores advierten un posible sentimiento de impunidad y riesgos para la seguridad si se otorgan indiscriminadamente, instando a criterios rigurosos para su concesión", "Cuestión de cobertura: se discute ampliar o restringir el catálogo de delitos excluidos de beneficios sustitutivos (actualmente ciertos delitos graves no permiten sustitución), evaluando el equilibrio entre la necesidad de castigo ejemplar y la conveniencia de alternativas a la prisión para rehabilitar al infractor"]'),
('DPNAL-026', 'Hurto', 'Derecho Penal', 'Delitos contra la Propiedad', 'Apropiación de cosa mueble ajena sin la voluntad de su dueño y con ánimo de lucro, realizada sin emplear fuerza en las cosas ni violencia o intimidación sobre las personas', 'Ej.: Tomar mercancías de una tienda y salir sin pagar, ocultándolas, configura un hurto (no hubo fuerza ni amenaza, solo apoderamiento clandestino)', 'Art. 432 CP (parte final, define hurto por exclusión de violencia o fuerza)', '', '', '["Debate sobre el momento consumativo: tradicionalmente se discutía si el hurto se consuma al solo tomar la cosa o al sacarla del ámbito del dueño"]'),
('DPNAL-027', 'Robo', 'Derecho Penal', 'Delitos contra la Propiedad', 'Apropiación de cosa mueble ajena con ánimo de lucro, ejecutada mediante fuerza en las cosas o violencia o intimidación en las personas para lograr la sustracción', 'Ej.: Un asaltante que amenaza con un arma a una persona y le quita su cartera comete robo con intimidación', 'si forzó la cerradura de una casa para entrar y sustraer objetos, es robo con fuerza en las cosas', 'Art. 432 CP (definición de robo)', '', '["CS, “Carrasco Romero” (2025): La Corte sostuvo que en el delito de robo la sustracción se considera consumada con la sola apropiación bajo intimidación, sin exigir que el ladrón se aleje del lugar con la cosa, aplicando la regla especial de consumación en robos"]'),
('DPNAL-028', 'Estafa', 'Derecho Penal', 'Delitos contra la Propiedad', 'Fraude patrimonial consistente en inducir a error a otra persona mediante engaño, logrando que voluntariamente realice un acto de disposición en perjuicio de su propio patrimonio o el de un tercero', 'Ej.: El clásico “cuento del tío” donde mediante mentiras (engaño sobre un premio inexistente) la víctima entrega dinero al estafador creyendo una falsedad, configurando delito de estafa', 'Art. 467 CP (definición de estafa)', '', '', '["La jurisprudencia exige para la estafa: a) un engaño astuto o fraude idóneo, b) un error o engaño efectivo en la víctima, c) un acto de disposición patrimonial realizado por la víctima en base al error, y d) un perjuicio patrimonial, constituyendo todos estos elementos la doctrina del “cuarteto clásico” de la estafa", "Fraudes masivos modernos (ej. estafas piramidales o vía internet) han tensionado la tipicidad clásica: tribunales han debido interpretar la noción de “engaño suficiente” en contextos más complejos, discutiéndose si el mero incumplimiento de una promesa comercial configura estafa o es ámbito civil", "Problema de concurso: se debate si ciertas conductas fraudulentas encajan como estafa o en tipos especiales (p.ej. estafa vs infracción Ley de Bancos en defraudaciones financieras), lo cual ha llevado a soluciones contradictorias sobre la aplicación preferente de tipo general o especial"]'),
('DPNAL-029', 'Apropiación indebida', 'Derecho Penal', 'Delitos contra la Propiedad', 'Delito de defraudación que ocurre cuando alguien se apropia o distrae en beneficio propio dinero, efectos u otra cosa mueble ajena que se le había confiado (en depósito, comisión, administración u otra obligación de entrega o devolución)', 'Ej.: Un administrador de fondos que recibe dinero de clientes para invertir y luego lo utiliza para gastos personales, negándose a devolverlo, comete apropiación indebida', 'Art. 470 N°1 CP', '', '', '["La doctrina jurisprudencial señala que en la apropiación indebida el sujeto activo inicialmente posee legítimamente la cosa ajena (tenencia precaria) y luego, con ánimo de lucro, la hace suya contrariando la obligación de restituir, distinguiéndola del hurto donde la tenencia es ilícita desde el inicio", "Debate sobre su alcance vs estafa: se discute si ciertos incumplimientos contractuales graves caen en el ámbito penal como apropiación indebida o se limitan al ámbito civil"]'),
('DPNAL-030', 'Daños', 'Derecho Penal', 'Delitos contra la Propiedad', 'Delito que consiste en causar destrucción, deterioro o menoscabo en cosa mueble o inmueble ajena, sin robarla, afectando el patrimonio del dueño', 'Ej.: Romper intencionalmente los vidrios de un vehículo ajeno o rayar con pintura las paredes de un local comercial constituye delito de daños a la propiedad', 'Art. 484 CP (configura delito de daños cualquier destrucción en propiedad ajena no cubierta por figuras especiales)', '', '', '["La jurisprudencia ha considerado que para la configuración del delito de daños debe acreditarse la malicia o intención deliberada de causar el menoscabo, distinguiéndolo de meros accidentes sin dolo que quedarían fuera del tipo penal", "Problema del valor del daño: el Código Penal gradúa las penas de daños según el monto del perjuicio (umbral de 40 UTM para distinguir delito de mayor gravedad), lo que genera debate en la práctica sobre la correcta tasación pericial del daño y si daños de escasa cuantía deben perseguirse penalmente o por vía civil", "Conflicto con la libertad de expresión en casos de daño en protestas: se discute doctrinariamente si ciertos daños al mobiliario urbano durante manifestaciones pudieran justificarse en algún caso por derechos fundamentales, pero la postura prevalente los considera delitos comunes de daños sin admitir causas políticas como justificación"]'),
('DPNAL-031', 'Homicidio', 'Derecho Penal', 'Delitos contra las Personas', 'Dar muerte a otro ser humano de forma intencional y antijurídica, sin que concurran las circunstancias especiales que configuran parricidio o femicidio', 'Ej.: Un individuo que, tras una riña, apuñala mortalmente a un desconocido comete homicidio simple', 'Art. 391 CP (define homicidio y prevé penas según agravantes calificantes)', '', '', '["La jurisprudencia distingue homicidio calificado (aquellos con agravantes como alevosía, ensañamiento, premeditación) del simple, aplicando penas superiores en el primero", "Debate sobre dolo eventual en homicidio: se discute si conductas con probablemente letales aceptadas por el agente (ej. conducir ebrio a gran velocidad causando muerte) deben subsumirse en homicidio doloso (eventual) o cuasidelito de homicidio, existiendo fallos contradictorios y desarrollo doctrinal tenso al al respecto", "Cuestión política-criminal: ante el incremento de homicidios, se ha planteado endurecer penas o limitar beneficios a condenados por este delito, lo que genera debate entre garantismo (evitar populismo penal) y demandas sociales de mayor rigor en sanciones por la vida humana"]'),
('DPNAL-032', 'Parricidio', 'Derecho Penal', 'Delitos contra las Personas', 'Homicidio agravado cometido contra una persona con lazo de parentesco cercano o relación de familia con el autor: padre, madre, hijo, u otro ascendiente o descendiente consanguíneo, así como el cónyuge o conviviente actual o anterior del autor', 'Ej.: Si un hijo mayor de edad, conociendo ese vínculo, da muerte a su padre, el delito se califica como parricidio, sancionado más gravemente que un homicidio común', 'Art. 390 CP', '', '', '["En jurisprudencia, el parricidio ha sido interpretado estrictamente exigiendo prueba fehaciente del vínculo (ej. partida de nacimiento, matrimonio o convivencia acreditada) para su configuración, anulándose fallos en que no se demostró plenamente la relación parental", "Controversia por extensión a convivientes: la inclusión del conviviente civil o de hecho en el tipo de parricidio (Ley 20.480) generó debate sobre si equiparar esas relaciones a las legales era correcto"]'),
('DPNAL-033', 'Femicidio', 'Derecho Penal', 'Delitos contra las Personas', 'Tipo penal que sanciona el homicidio cuando la víctima es una mujer asesinada por un hombre con quien tiene o ha tenido una relación íntima de pareja (cónyuge, conviviente, relación sentimental), o cuando es motivado por razones de género (odio, menosprecio por su condición de mujer)', 'Ej.: El asesinato de una mujer a manos de su ex cónyuge en venganza porque ella terminó la relación constituye un femicidio íntimo', 'Art. 390 bis y 390 ter CP', '', '', '["La jurisprudencia reciente ha comenzado a aplicar el tipo de femicidio introducido en 2020, enfatizando en algunos fallos la necesidad de probar las motivaciones de género (cuando se invoca el femicidio por razón de género del Art. 390 ter) mediante indicios claros de odio o menosprecio a la víctima por su condición, para diferenciarlo de un homicidio simple", "Debate social y jurídico: el femicidio se incorporó para visibilizar y agravar la violencia de género letal, pero se discute si dejar excluidos supuestos (como víctima hombre trans o casos de mujeres que matan a mujeres en contexto de pareja) puede generar vacíos de protección, proponiéndose eventualmente neutralizar el tipo o complementarlo", "Señalamientos de ciertos sectores sobre presunta discriminación del tipo: se argumenta que establece una asimetría penal por razón de sexo del autor (solo hombre puede cometer femicidio), lo que ha sido defendido por la mayoría como una medida legítima de acción afirmativa dada la prevalencia de la violencia machista en la realidad que busca abordar"]'),
('DPNAL-034', 'Lesiones graves', 'Derecho Penal', 'Delitos contra las Personas', 'Daños corporales inferidos a una persona que menoscaban gravemente su salud o integridad, ya sea causando un daño permanente (por ej. pérdida o inutilidad de un órgano, miembro o sentido) o provocando una incapacidad para el trabajo o enfermedad por un período prolongado (más de 30 días)', 'Ej.: Golpes que dejan a la víctima con una fractura complicada y postrada por dos meses configuran lesiones graves', 'Art. 397 N°1 y N°2 CP', '', '', '["En fallos reiterados, la Corte Suprema ha exigido para tener por probadas las lesiones graves un informe médico legal que certifique la naturaleza y duración de las heridas, sentando la necesidad de respaldo pericial objetivo para la calificación jurídica", "Controversia en torno a las secuelas psíquicas: se discute si un daño psicológico profundo y permanente puede encuadrarse en lesiones graves gravísimas (equiparable a inutilidad para el trabajo), cuestión que ha sido objeto de opiniones divergentes periciales y jurídicas, con algunos tribunales reconociéndolo y otros que no por apego a la literalidad física del artículo", "Además, la aplicación de la agravante de lesiones gravísimas vs graves ha generado debate cuando la víctima sufre, por ejemplo, pérdida de un diente o cicatriz notable: la jurisprudencia a veces difiere sobre si son deformidades relevantes (gravísimas) o meras lesiones graves, evidenciando margen de apreciación subjetiva"]'),
('DPNAL-035', 'Lesiones leves', 'Derecho Penal', 'Delitos contra las Personas', 'Lesiones o heridas que solo causan daño menor a la salud o integridad corporal de la víctima, generalmente caracterizadas por una incapacidad o enfermedad de poca duración (por lo general hasta 7 días) o sin dejar secuelas significativas', 'Ej.: Un puñetazo que provoca contusiones y equimosis que sanan en una semana se considera lesión leve, sancionada usualmente como falta o delito menor', 'Art. 494 N°5 CP (falta penal por lesiones leves entre particulares)', '', '', '["La jurisprudencia menor (juzgados de garantía) suele resolver las lesiones leves mediante salidas alternativas, destacando el principio de oportunidad en lesiones de mínima entidad, aunque exigiendo igualmente la constatación médica del carácter leve de las mismas", "Debate acerca de la acción penal: tradicionalmente las lesiones leves requieren instancia particular (querella de la víctima) para perseguirse, mientras las graves se investigan de oficio, lo cual algunos cuestionan proponiendo perseguir de oficio toda lesión para no desproteger casos de víctimas que no denuncian por temor", "Asimismo, se discute si ciertas lesiones leves en contexto de violencia intrafamiliar debe recibir un trato más severo pese a su menor entidad, dado el contexto de reiteración y dominio, generando iniciativas legales para agravar esas conductas pese a ser \"leves\" en resultado médico"]');